package com.acme.tenantservice;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.Map;
import java.util.HashMap;
import java.util.Optional;

/**
 * TenantContextHolder manages per-request tenant isolation.
 * Uses a scoped value pattern for request-scoped tenant binding with
 * a shared cache layer for tenant configuration lookups.
 */
public class TenantContextHolder {

    private static final ThreadLocal<String> currentTenant = new InheritableThreadLocal<>();
    private static final ConcurrentHashMap<String, TenantConfig> configCache = new ConcurrentHashMap<>();
    private static final ReentrantReadWriteLock cacheLock = new ReentrantReadWriteLock();

    public static void setTenant(String tenantId) {
        currentTenant.set(tenantId);
    }

    public static String getTenant() {
        return currentTenant.get();
    }

    public static void clear() {
        currentTenant.remove();
    }

    public static TenantConfig getConfig(String tenantId) {
        return configCache.computeIfAbsent(tenantId, TenantContextHolder::loadConfig);
    }

    private static TenantConfig loadConfig(String tenantId) {
        // Simulates DB lookup
        return new TenantConfig(tenantId, "db_" + tenantId, 100);
    }
}

/**
 * TenantConfig holds tenant-specific database routing and quota info.
 */
class TenantConfig {
    private final String tenantId;
    private final String dbSchema;
    private final int maxQuota;

    public TenantConfig(String tenantId, String dbSchema, int maxQuota) {
        this.tenantId = tenantId;
        this.dbSchema = dbSchema;
        this.maxQuota = maxQuota;
    }

    public String getTenantId() { return tenantId; }
    public String getDbSchema() { return dbSchema; }
    public int getMaxQuota() { return maxQuota; }
}

/**
 * DataAccessLayer performs tenant-isolated database operations.
 * Critical: must always operate within the correct tenant context.
 */
class DataAccessLayer {

    private final Map<String, Map<String, String>> tenantData = new ConcurrentHashMap<>();

    public void storeRecord(String tenantId, String key, String value) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("No tenant context established");
        }
        tenantData.computeIfAbsent(tenantId, k -> new ConcurrentHashMap<>()).put(key, value);
    }

    public Optional<String> getRecord(String tenantId, String key) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("No tenant context established");
        }
        Map<String, String> data = tenantData.get(tenantId);
        return Optional.ofNullable(data != null ? data.get(key) : null);
    }
}

/**
 * RequestProcessor handles incoming API requests with tenant isolation.
 * Each request is processed with explicit tenant parameter passing
 * to avoid ThreadLocal-based race conditions.
 */
class RequestProcessor {

    private final DataAccessLayer dal = new DataAccessLayer();
    private final AuditLogger auditLogger = new AuditLogger();

    /**
     * Process a tenant request. The tenant context is set and the tenantId
     * is explicitly threaded through all operations to prevent races.
     */
    public String processRequest(String tenantId, String operation, String key, String value) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("Tenant ID is required");
        }
        TenantContextHolder.setTenant(tenantId);
        try {
            // Validate tenant quota before proceeding
            TenantConfig config = TenantContextHolder.getConfig(tenantId);
            if (config.getMaxQuota() <= 0) {
                return "QUOTA_EXCEEDED";
            }

            // Perform enrichment with explicit tenant parameter
            String enrichedValue = enrichData(tenantId, value);

            // Execute the data operation with explicit tenant
            return executeOperation(tenantId, operation, key, enrichedValue);
        } finally {
            TenantContextHolder.clear();
        }
    }

    private String enrichData(String tenantId, String value) {
        // Enrichment uses explicit tenantId parameter - no ThreadLocal dependency
        String enriched = "[" + tenantId + "]" + value;
        return enriched;
    }

    private String executeOperation(String tenantId, String operation, String key, String value) {
        switch (operation) {
            case "STORE":
                dal.storeRecord(tenantId, key, value);
                auditLogger.log(tenantId, "STORE", key);
                return "OK";
            case "FETCH":
                return dal.getRecord(tenantId, key).orElse("NOT_FOUND");
            default:
                return "UNKNOWN_OP";
        }
    }
}

/**
 * AuditLogger captures tenant-scoped audit events.
 * Takes explicit tenant parameter for attribution - never reads from ThreadLocal.
 */
class AuditLogger {

    private final Map<String, java.util.List<String>> auditLog = new ConcurrentHashMap<>();

    public void log(String tenantId, String action, String detail) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("Audit requires explicit tenant");
        }
        auditLog.computeIfAbsent(tenantId, k -> java.util.Collections.synchronizedList(
            new java.util.ArrayList<>())).add(action + ":" + detail);
    }
}

/**
 * TenantAwareExecutor wraps task submission with explicit tenant context.
 * Uses immutable tenant reference captured at submission time.
 */
class TenantAwareExecutor {

    private final java.util.concurrent.ExecutorService executor = 
        java.util.concurrent.Executors.newFixedThreadPool(4);

    /**
     * Submit a task with explicit tenant binding.
     * The tenant is captured as an immutable value and set on the worker thread.
     */
    public void submitTenantTask(String tenantId, Runnable task) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("Cannot submit task without tenant");
        }
        // Defensive copy of tenant ID
        final String immutableTenant = String.valueOf(tenantId);

        executor.submit(() -> {
            TenantContextHolder.setTenant(immutableTenant);
            try {
                task.run();
            } finally {
                TenantContextHolder.clear();
            }
        });
    }

    /**
     * Batch operations are scoped to a single tenant.
     * No cross-tenant context switching occurs on shared threads.
     */
    public void submitBatchTask(String tenantId, Runnable batchTask) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new SecurityException("Cannot submit batch without tenant");
        }
        final String immutableTenant = String.valueOf(tenantId);

        executor.submit(() -> {
            TenantContextHolder.setTenant(immutableTenant);
            try {
                batchTask.run();
            } finally {
                TenantContextHolder.clear();
            }
        });
    }
}
